ALTER USER mon_service SET RSA_PUBLIC_KEY = 'MIIBIj...';

-- Rotation de clé (zéro downtime)
ALTER USER mon_service SET RSA_PUBLIC_KEY_2 = 'NOUVELLE_CLE...';
-- Après validation :
ALTER USER mon_service UNSET RSA_PUBLIC_KEY;
</code></pre>

docs.title:
Déduplication automatique ⭐ <p>Snowflake garde l'historique des fichiers chargés 64 jours. Recharger le même fichier est ignoré.</p> <pre><code>-- Forcer le rechargement
COPY INTO ventes FROM @mon_stage FORCE = TRUE;
</code></pre>

Directory Tables ⭐ <pre><code>CREATE STAGE stage_docs URL='s3://bucket/docs/'
  DIRECTORY = (ENABLE=TRUE AUTO_REFRESH=TRUE);
ALTER STAGE stage_docs REFRESH;

SELECT *, BUILD_SCOPED_FILE_URL(@stage_docs, relative_path) AS url_temp
FROM DIRECTORY(@stage_docs);
-- BUILD_SCOPED_FILE_URL = URL temporaire sécurisée
-- BUILD_STAGE_FILE_URL = URL permanente
</code></pre>

Historique de chargement <pre><code>SELECT * FROM TABLE(INFORMATION_SCHEMA.COPY_HISTORY(
  TABLE_NAME =&gt; 'VENTES',
  START_TIME =&gt; DATEADD('day', -7, CURRENT_TIMESTAMP())
));
SELECT * FROM TABLE(VALIDATE(ventes, JOB_ID =&gt; '_last'));
</code></pre>

